 module=inputs.original('_gnu_supervisor_inverse_runner','scripts/ci/glibc-owned-runtime/runner.py');raw=__import__('pathlib').Path(module.__file__).read_bytes();inputs.need(_pin(raw)==HELD_RUNNER_PIN,'same whole held original runner for inverse');old=ast.get_source_segment(raw.decode(),next(n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef)and n.name=='run_command'));service,changes=_service_seams(old);restored=text.replace(COMMAND_BODY,service,1)
 for a,b in reversed(changes):inputs.need(restored.count(b)==1,'one inverse service seam');restored=restored.replace(b,a,1)
